// Geometric Constructions: Afrikaans lesson text (keys: the English with numbers as {0}, {1}…).
(function () {
  const T = {};
  const SHOW = " Toon al die konstruksies vir die raaklyne en raakboë.";
  // "Copy a figure" exercises: the GIVEN step and the repeated tangent/arc steps.
  [["rocker arm", "wipperarm", "A, B, C"], ["concave link", "hol skakel", "A, B"], ["mounting plate", "monteerplaat", "A, B, C, D"],
   ["cam lever", "nokhefboom", "A, B"], ["triangular link plate", "driehoekige skakelplaat", "A, B, C"], ["crank", "kruk", "A, B"],
   ["bell crank", "klokkruk", "A, B, C"], ["pedal arm", "pedaalarm", "A, B, C"], ["clamp jaw", "klembek", "A, B, C, D"],
   ["hanger bracket", "hangerhakie", "A, B, C"]].forEach(function (f) {
    T["GIVEN: the " + f[0] + " (see the specification). Copy it to scale {0}:{1}, starting with centre A at S. Show ALL constructions. First draw the centre lines of every boss: " + f[2] + "."] =
      "GEGEE: die " + f[1] + " (sien die spesifikasie). Kopieer dit op skaal {0}:{1}, en begin met middelpunt A by S. Toon AL die konstruksies. Trek eers die middellyne van elke naaf: " + f[2] + ".";
  });
  [["C", "A"], ["B", "A"], ["C", "D"]].forEach(function (p) {
    T["R{0} ARC BETWEEN " + p[0] + " AND " + p[1] + ": from " + p[0] + " draw an arc of radius {1} ({2} + {3}), and from " + p[1] + " one of radius {4} ({5} + {6}). They cross at O{7}."] =
      "R{0}-BOOG TUSSEN " + p[0] + " EN " + p[1] + ": trek vanaf " + p[0] + " 'n boog met radius {1} ({2} + {3}), en vanaf " + p[1] + " een met radius {4} ({5} + {6}). Hulle kruis by O{7}.";
    T["Join O{0} to " + p[0] + " and to " + p[1] + ": the tangent points. With centre O{1}, draw the R{2} arc between them."] =
      "Verbind O{0} met " + p[0] + " en met " + p[1] + ": die raakpunte. Trek met middelpunt O{1} die R{2}-boog tussen hulle.";
  });
  [["B", "C"], ["B", "A"]].forEach(function (p) {
    T["R{0} ARC ROUND " + p[0] + " AND " + p[1] + ": from " + p[0] + " draw an arc of radius {1} ({2} − {3}), and from " + p[1] + " one of radius {4} ({5} − {6}). They cross at O{7}."] =
      "R{0}-BOOG OM " + p[0] + " EN " + p[1] + ": trek vanaf " + p[0] + " 'n boog met radius {1} ({2} − {3}), en vanaf " + p[1] + " een met radius {4} ({5} − {6}). Hulle kruis by O{7}.";
    T["Draw lines from O{0} through " + p[0] + " and " + p[1] + ", extended to the circles: the tangent points. With centre O{1}, draw the R{2} arc between them."] =
      "Trek lyne vanaf O{0} deur " + p[0] + " en " + p[1] + ", verleng tot by die sirkels: die raakpunte. Trek met middelpunt O{1} die R{2}-boog tussen hulle.";
  });
  ["BC", "DA", "AB"].forEach(function (p) {
    T["TANGENT " + p + " (equal radii): draw lines square to " + p + " through both centres. They cut the circles at the tangent points; join them."] =
      "RAAKLYN " + p + " (gelyke radiusse): trek lyne haaks op " + p + " deur albei middelpunte. Hulle sny die sirkels by die raakpunte; verbind hulle.";
  });
  ["AB", "BA"].forEach(function (p) {
    T["TANGENT " + p + ": from the centre of the larger circle draw a thin circle of radius {0} (the difference of the radii). Bisect " + p + " and draw a semicircle on it to cut the thin circle at K."] =
      "RAAKLYN " + p + ": trek vanaf die middelpunt van die groter sirkel 'n dun sirkel met radius {0} (die verskil van die radiusse). Halveer " + p + " en trek 'n halfsirkel daarop om die dun sirkel by K te sny.";
  });

  Object.assign(T, {
    "Bisect a Straight Line": "Halveer 'n reguit lyn",
    "Find the exact midpoint of a line and construct a line perpendicular to it, using only a compass and straightedge.": "Vind die presiese middelpunt van 'n lyn en konstrueer 'n lyn loodreg daarop, met net 'n passer en reguitrand.",
    "Bisect line AB ({0} mm) using compass and straightedge. Show all construction arcs and label points P, Q and M.": "Halveer lyn AB ({0} mm) met 'n passer en reguitrand. Toon al die konstruksieboë en benoem punte P, Q en M.",
    "Draw line AB, {0} mm long, using a Type A (continuous thick) line.": "Trek lyn AB, {0} mm lank, met 'n tipe A-lyn (aaneenlopend dik).",
    "From A, open your compass to more than half of AB — use {0} mm. Swing one arc above the line and one below it.": "Maak vanaf A jou passer meer as die helfte van AB oop — gebruik {0} mm. Swaai een boog bo die lyn en een daaronder.",
    "Keeping the same radius, swing two more arcs from B. Where the arcs cross above and below AB, mark points Q and P.": "Hou dieselfde radius en swaai nog twee boë vanaf B. Waar die boë bo en onder AB kruis, merk punte Q en P.",
    "Join P to Q with a Type A line. PQ is the perpendicular bisector of AB — it crosses AB at its midpoint, M, at exactly {0}°.": "Verbind P met Q met 'n tipe A-lyn. PQ is die middelloodlyn van AB — dit kruis AB by sy middelpunt, M, teen presies {0}°.",
    "Bisect an Angle": "Halveer 'n hoek",
    "Divide an angle into two exactly equal parts using compass and straightedge.": "Verdeel 'n hoek in twee presies gelyke dele met 'n passer en reguitrand.",
    "Bisect angle AVC (approximately {0}°) using compass and straightedge. Show all construction arcs.": "Halveer hoek AVC (ongeveer {0}°) met 'n passer en reguitrand. Toon al die konstruksieboë.",
    "Draw angle AVC at vertex V, with arms VA and VC (approximately {0}° apart).": "Teken hoek AVC by hoekpunt V, met bene VA en VC (ongeveer {0}° uitmekaar).",
    "From V, swing a single arc (radius {0} mm) crossing both arms. Mark the crossing points X and Y.": "Swaai vanaf V 'n enkele boog (radius {0} mm) wat albei bene kruis. Merk die kruispunte X en Y.",
    "From X and Y, swing two equal arcs of the same radius so they cross at point D.": "Swaai vanaf X en Y twee gelyke boë met dieselfde radius sodat hulle by punt D kruis.",
    "Join V to D with a Type A line. VD bisects angle AVC into two equal {0}° angles.": "Verbind V met D met 'n tipe A-lyn. VD halveer hoek AVC in twee gelyke hoeke van {0}°.",
    "Dividing a Line into Equal Parts (Compass, Set Square & Ruler)": "'n Lyn in gelyke dele verdeel (passer, tekendriehoek en liniaal)",
    "Divide any line into any number of exactly equal parts using a random auxiliary line, a compass, and a set square sliding along a ruler — the technique behind every evenly spaced graph axis or loci grid.": "Verdeel enige lyn in enige aantal presies gelyke dele met 'n willekeurige hulplyn, 'n passer, en 'n tekendriehoek wat langs 'n liniaal skuif — die tegniek agter elke eweredig verdeelde grafiekas of lokusrooster.",
    "Divide a {0} mm line AB into {1} equal parts, using a random auxiliary line, compass divisions, and a set square on a ruler to project the divisions onto AB. Show all construction lines.": "Verdeel 'n lyn AB van {0} mm in {1} gelyke dele, met 'n willekeurige hulplyn, passerverdelings, en 'n tekendriehoek op 'n liniaal om die verdelings op AB te projekteer. Toon al die konstruksielyne.",
    "Draw the line to be divided, AB ({0} mm), and decide how many equal parts you need — here, {1}.": "Trek die lyn wat verdeel moet word, AB ({0} mm), en besluit hoeveel gelyke dele jy nodig het — hier {1}.",
    "From A, draw a random auxiliary line — any convenient angle, any length, as long as it is not along AB.": "Trek vanaf A 'n willekeurige hulplyn — enige gerieflike hoek, enige lengte, solank dit nie langs AB lê nie.",
    "With your compass set to any convenient radius, step off {0} equal divisions along the auxiliary line from A. Mark points {1}–{2}.": "Stel jou passer op enige gerieflike radius en stap {0} gelyke verdelings langs die hulplyn vanaf A af. Merk punte {1}–{2}.",
    "Join point {0} to B with a straight line.": "Verbind punt {0} met B met 'n reguit lyn.",
    "Place a set square against a ruler so one edge runs parallel to line {0}–B. Slide the set square along the ruler and draw a parallel line through each of points {1}–{2} — where each one crosses AB is a division point.": "Plaas 'n tekendriehoek teen 'n liniaal sodat een rand ewewydig aan lyn {0}–B loop. Skuif die tekendriehoek langs die liniaal en trek 'n ewewydige lyn deur elk van punte {1}–{2} — waar elkeen AB kruis, is 'n verdelingspunt.",
    "AB is now divided into {0} exactly equal parts ({1} mm each) — even though it was never measured or divided directly. This is the technique behind every evenly spaced axis, from displacement–time graphs to loci diagrams.": "AB is nou in {0} presies gelyke dele ({1} mm elk) verdeel — al is dit nooit direk gemeet of verdeel nie. Dit is die tegniek agter elke eweredig verdeelde as, van verplasing-tyd-grafieke tot lokusdiagramme.",
    "Tangent to a Circle from an External Point": "Raaklyn aan 'n sirkel vanaf 'n punt buite",
    "Construct the two tangent lines from a point outside a circle, using the Thales semicircle method.": "Konstrueer die twee raaklyne vanaf 'n punt buite 'n sirkel, met Thales se halfsirkelmetode.",
    "Construct the two tangents from external point P to a circle of radius {0} mm, given OP = {1} mm. Show the construction circle and label the tangent points.": "Konstrueer die twee raaklyne vanaf 'n punt P buite 'n sirkel met radius {0} mm, gegee OP = {1} mm. Toon die konstruksiesirkel en benoem die raakpunte.",
    "Draw circle O, radius {0} mm. Mark external point P, {1} mm from O.": "Trek sirkel O, radius {0} mm. Merk die buitepunt P, {1} mm van O.",
    "Bisect OP to find its midpoint, N.": "Halveer OP om sy middelpunt, N, te vind.",
    "With centre N and radius NO, draw a circle. It crosses the original circle at the two tangent points, T{0} and T{1}.": "Trek met middelpunt N en radius NO 'n sirkel. Dit kruis die oorspronklike sirkel by die twee raakpunte, T{0} en T{1}.",
    "Join P to T{0} and P to T{1} with Type A lines. These are the two required tangents — each meets the circle at exactly {2}° to the radius.": "Verbind P met T{0} en P met T{1} met tipe A-lyne. Dit is die twee vereiste raaklyne — elkeen ontmoet die sirkel teen presies {2}° met die radius.",
    "Regular Hexagon — Inscribed in a Circle (Distance Across Corners)": "Reëlmatige seshoek — in 'n sirkel ingeskryf (afstand oor die hoeke)",
    "Construct a regular hexagon using the compass-step method — for a hexagon, the compass radius never changes. Use this when the distance ACROSS CORNERS (the circumscribing circle) is given.": "Konstrueer 'n reëlmatige seshoek met die passerstapmetode — vir 'n seshoek verander die passerradius nooit nie. Gebruik dit wanneer die afstand OOR DIE HOEKE (die omgeskrewe sirkel) gegee is.",
    "Inscribe a regular hexagon in a circle of {0} mm diameter, using the compass-step method. Label all six vertices.": "Skryf 'n reëlmatige seshoek in 'n sirkel met 'n middellyn van {0} mm in, met die passerstapmetode. Benoem al ses hoekpunte.",
    "Draw a circle of radius {0} mm, centre O. Mark point {1} where it crosses the vertical centre line at the top.": "Trek 'n sirkel met radius {0} mm, middelpunt O. Merk punt {1} waar dit bo die vertikale middellyn kruis.",
    "A regular hexagon's side length always equals the circle's radius. Without changing your compass, step from point {0} around the circle to mark point {1}.": "'n Reëlmatige seshoek se sylengte is altyd gelyk aan die sirkel se radius. Stap sonder om jou passer te verander vanaf punt {0} om die sirkel om punt {1} te merk.",
    "Keep the same radius and step around again to mark point {0}.": "Hou dieselfde radius en stap weer om om punt {0} te merk.",
    "Join points {0}–{1} in order with Type A lines to complete the hexagon.": "Verbind punte {0}–{1} in volgorde met tipe A-lyne om die seshoek te voltooi.",
    "Regular Hexagon — Circumscribed About a Circle (Distance Across Flats)": "Reëlmatige seshoek — om 'n sirkel omgeskryf (afstand oor die plat kante)",
    "Construct a regular hexagon around a given circle using six tangent lines, {0}° apart. Use this when the distance ACROSS FLATS (the inscribed circle) is given instead of the distance across corners.": "Konstrueer 'n reëlmatige seshoek om 'n gegewe sirkel met ses raaklyne, {0}° uitmekaar. Gebruik dit wanneer die afstand OOR DIE PLAT KANTE (die ingeskrewe sirkel) gegee is in plaas van die afstand oor die hoeke.",
    "Circumscribe a regular hexagon about a circle of {0} mm diameter (the inscribed circle), using the tangent method. Label all six vertices.": "Skryf 'n reëlmatige seshoek om 'n sirkel met 'n middellyn van {0} mm (die ingeskrewe sirkel) om, met die raaklynmetode. Benoem al ses hoekpunte.",
    "Draw a circle of radius {0} mm, centre O — this is the hexagon's INSCRIBED circle (its diameter is the \"distance across flats\"). Draw a radius straight up to locate the first point of tangency.": "Trek 'n sirkel met radius {0} mm, middelpunt O — dit is die seshoek se INGESKREWE sirkel (sy middellyn is die \"afstand oor die plat kante\"). Trek 'n radius reguit op om die eerste raakpunt te vind.",
    "At that point, draw a line perpendicular to the radius — a Type A line, exactly one side-length long ({0} mm), centred on the point. This is the hexagon's top side.": "Trek by daardie punt 'n lyn loodreg op die radius — 'n tipe A-lyn, presies een sylengte lank ({0} mm), met die punt in die middel. Dit is die seshoek se boonste sy.",
    "Repeat at the other five points, {0}° apart around the circle — draw the next radius, then its perpendicular tangent side.": "Herhaal by die ander vyf punte, {0}° uitmekaar om die sirkel — trek die volgende radius, dan sy loodregte raaksy.",
    "Continue around the circle: radius, then perpendicular tangent side, at every {0}°.": "Gaan voort om die sirkel: radius, dan loodregte raaksy, by elke {0}°.",
    "Where each pair of adjacent tangent lines meets is a vertex of the hexagon. Label them {0}–{1} — the outline is already complete.": "Waar elke paar aangrensende raaklyne ontmoet, is 'n hoekpunt van die seshoek. Benoem hulle {0}–{1} — die buitelyn is reeds voltooi.",
    "Regular Pentagon — Protractor Method (Given the Circumscribing Circle)": "Reëlmatige vyfhoek — gradeboogmetode (omgeskrewe sirkel gegee)",
    "Construct a regular pentagon by dividing a given circle into {0} equal {1}° central angles with a protractor — used when the circumscribing circle is what you're given.": "Konstrueer 'n reëlmatige vyfhoek deur 'n gegewe sirkel met 'n gradeboog in {0} gelyke middelpuntshoeke van {1}° te verdeel — gebruik wanneer die omgeskrewe sirkel gegee is.",
    "Inscribe a regular pentagon in a circle of {0} mm diameter, dividing it into {1} equal {2}° angles. Label all five vertices.": "Skryf 'n reëlmatige vyfhoek in 'n sirkel met 'n middellyn van {0} mm in, deur dit in {1} gelyke hoeke van {2}° te verdeel. Benoem al vyf hoekpunte.",
    "Draw a circle of radius {0} mm, centre O. Mark point {1} at the top, where it crosses the vertical centre line.": "Trek 'n sirkel met radius {0} mm, middelpunt O. Merk punt {1} bo, waar dit die vertikale middellyn kruis.",
    "A regular pentagon divides the circle into {0} equal angles at the centre: {1}° ÷ {2} = {3}°. Using a protractor at O, mark point {4}, {5}° from point {6}.": "'n Reëlmatige vyfhoek verdeel die sirkel in {0} gelyke hoeke by die middelpunt: {1}° ÷ {2} = {3}°. Merk met 'n gradeboog by O punt {4}, {5}° van punt {6}.",
    "Continue marking every {0}° around the circle to place point {1}.": "Gaan voort om elke {0}° om die sirkel te merk om punt {1} te plaas.",
    "Join points {0}–{1} in order with Type A lines to complete the pentagon.": "Verbind punte {0}–{1} in volgorde met tipe A-lyne om die vyfhoek te voltooi.",
    "Regular Pentagon — Given a Side (Bisection Method)": "Reëlmatige vyfhoek — sy gegee (halveringsmetode)",
    "Construct a regular pentagon starting from one known side, using the perpendicular bisector and the golden ratio — no protractor required, and no circle given in advance.": "Konstrueer 'n reëlmatige vyfhoek vanaf een bekende sy, met die middelloodlyn en die guldesnede — geen gradeboog nodig nie, en geen sirkel vooraf gegee nie.",
    "Construct a regular pentagon on a given side AB = {0} mm, using the bisection (golden-ratio) method. Show all construction arcs and label points M, X, Y and the five vertices A–E.": "Konstrueer 'n reëlmatige vyfhoek op 'n gegewe sy AB = {0} mm, met die halverings- (guldesnede-) metode. Toon al die konstruksieboë en benoem punte M, X, Y en die vyf hoekpunte A–E.",
    "Draw the given side AB, {0} mm long, using a Type A line.": "Trek die gegewe sy AB, {0} mm lank, met 'n tipe A-lyn.",
    "Bisect AB (as in Construction {0}) to find its midpoint M, and extend the perpendicular bisector well above AB — it will pass through the pentagon's top vertex.": "Halveer AB (soos in konstruksie {0}) om sy middelpunt M te vind, en verleng die middelloodlyn ver bo AB — dit sal deur die vyfhoek se boonste hoekpunt gaan.",
    "At B, construct a line perpendicular to AB. With centre B and radius AB, mark point X on it, so BX = AB.": "Konstrueer by B 'n lyn loodreg op AB. Merk met middelpunt B en radius AB punt X daarop, sodat BX = AB.",
    "Join M to X. With centre M and radius MX, swing an arc to cut line AB produced (extended beyond A) at point Y.": "Verbind M met X. Swaai met middelpunt M en radius MX 'n boog om die verlengde lyn AB (verby A verleng) by punt Y te sny.",
    "With centre B and radius BY, swing an arc to cross the extended bisector above AB. This crossing point is D, the pentagon's top vertex.": "Swaai met middelpunt B en radius BY 'n boog om die verlengde middelloodlyn bo AB te kruis. Hierdie kruispunt is D, die vyfhoek se boonste hoekpunt.",
    "With centre B and centre D, both with radius AB, swing two arcs crossing to the right of the bisector. Their intersection is vertex C.": "Swaai met middelpunt B en middelpunt D, albei met radius AB, twee boë wat regs van die middelloodlyn kruis. Hulle snypunt is hoekpunt C.",
    "In the same way, with centre A and centre D, radius AB, swing two arcs crossing to the left of the bisector to find vertex E.": "Swaai op dieselfde manier met middelpunt A en middelpunt D, radius AB, twee boë wat links van die middelloodlyn kruis om hoekpunt E te vind.",
    "Join A–B–C–D–E–A in order with Type A lines to complete the pentagon.": "Verbind A–B–C–D–E–A in volgorde met tipe A-lyne om die vyfhoek te voltooi.",
    "Helix / Spring Curve": "Heliks / veerkromme",
    "Project one full turn of a helix from its plan (circle) and elevation (pitch) views — the method used to draw springs and screw threads.": "Projekteer een volle draai van 'n heliks uit sy plan- (sirkel-) en aansig- (steek-) aansigte — die metode waarmee vere en skroefdrade geteken word.",
    "Project one full turn of a helix curve (base circle {0} mm diameter, pitch {1} mm) from its plan and elevation views.": "Projekteer een volle draai van 'n helikskromme (basissirkel {0} mm middellyn, steek {1} mm) uit sy plan en aansig.",
    "TOP VIEW: draw a circle of {0} mm diameter with its centre lines, and divide it into {1} equal parts ({2}° apart). Number the points from {3} on the left, anticlockwise: a right-hand helix that rises turns anticlockwise seen from above.": "BOAANSIG: trek 'n sirkel met 'n middellyn van {0} mm met sy middellyne, en verdeel dit in {1} gelyke dele ({2}° uitmekaar). Nommer die punte vanaf {3} aan die linkerkant, antikloksgewys: 'n regshandige heliks wat styg, draai van bo gesien antikloksgewys.",
    "FRONT VIEW, below the top view: draw the base line and the outline of the cylinder. Mark the pitch ({0} mm, one full turn) up the side, divide it into {1} equal parts and draw thin horizontal lines through the marks.": "VOORAANSIG, onder die boaansig: trek die basislyn en die buitelyn van die silinder. Merk die steek ({0} mm, een volle draai) langs die kant op, verdeel dit in {1} gelyke dele en trek dun horisontale lyne deur die merke.",
    "Project each point of the top view straight down to ITS OWN height line: point {0} on line {1}, point {2} on line {3}, point {4} on line {5}, and so on up to point {6} again on line {7}. Mark where each projector crosses its line.": "Projekteer elke punt van die boaansig reguit af na SY EIE hoogtelyn: punt {0} op lyn {1}, punt {2} op lyn {3}, punt {4} op lyn {5}, ensovoorts tot by punt {6} weer op lyn {7}. Merk waar elke projeksielyn sy lyn kruis.",
    "Join the points with a smooth curve. Points {0} to {1} are on the FRONT of the cylinder (seen); points {2} to {3} are on the back (hidden). The front view of a helix is always a wave: one full wave per turn.": "Verbind die punte met 'n gladde kromme. Punte {0} tot {1} is aan die VOORKANT van die silinder (sigbaar); punte {2} tot {3} is aan die agterkant (versteek). Die vooraansig van 'n heliks is altyd 'n golf: een volle golf per draai.",
    "Ellipse — Concentric Circles Method": "Ellips — konsentriese-sirkelmetode",
    "Construct a true ellipse from its major and minor axes using two concentric circles, divided into {0} equal parts — no trammel or string needed.": "Konstrueer 'n ware ellips uit sy hoof- en neweas met twee konsentriese sirkels, in {0} gelyke dele verdeel — geen ellipspasser of tou nodig nie.",
    "Construct an ellipse with a {0} mm major axis and a {1} mm minor axis, using the concentric circles method. Divide both circles into {2} equal parts and show all construction lines.": "Konstrueer 'n ellips met 'n hoofas van {0} mm en 'n neweas van {1} mm, met die konsentriese-sirkelmetode. Verdeel albei sirkels in {2} gelyke dele en toon al die konstruksielyne.",
    "Draw two concentric circles at centre O: one with the major-axis radius ({0} mm), one with the minor-axis radius ({1} mm). Draw the horizontal major axis and vertical minor axis through O.": "Trek twee konsentriese sirkels by middelpunt O: een met die hoofas se radius ({0} mm), een met die neweas se radius ({1} mm). Trek die horisontale hoofas en vertikale neweas deur O.",
    "Divide both circles into {0} equal {1}° divisions, using the same radial construction lines for both.": "Verdeel albei sirkels in {0} gelyke verdelings van {1}°, met dieselfde radiale konstruksielyne vir albei.",
    "From each point on the OUTER circle, drop a vertical line. From the matching point on the INNER circle, draw a horizontal line. Mark where each pair meets — that intersection is a point on the ellipse.": "Laat vanaf elke punt op die BUITESTE sirkel 'n vertikale lyn sak. Trek vanaf die ooreenstemmende punt op die BINNESTE sirkel 'n horisontale lyn. Merk waar elke paar ontmoet — daardie snypunt is 'n punt op die ellips.",
    "Join the {0} points with a smooth curve — this is a true ellipse, not an approximation.": "Verbind die {0} punte met 'n gladde kromme — dit is 'n ware ellips, nie 'n benadering nie.",
    "Tangent Arc Blend — Rounded-End Link": "Raakboogaansluiting — skakel met ronde ente",
    "Construct a rounded-end connecting link — the classic \"tangent arc\" mechanical outline, where two straight sides blend smoothly into semicircular ends of equal radius.": "Konstrueer 'n verbindingskakel met ronde ente — die klassieke meganiese \"raakboog\"-buitelyn, waar twee reguit kante glad oorgaan in halfsirkelvormige ente met gelyke radius.",
    "Construct a rounded-end link: two mounting holes {0} mm apart, arm width {1} mm. Show the guide circles, the tangent straight sides, and the two end arcs. Correct tangent construction must be shown at all times.": "Konstrueer 'n skakel met ronde ente: twee monteergate {0} mm uitmekaar, armbreedte {1} mm. Toon die hulpsirkels, die reguit raakkante, en die twee endboë. Korrekte raakkonstruksie moet te alle tye gewys word.",
    "Draw the centre line and mark the two hole centres, {0} mm apart.": "Trek die middellyn en merk die twee gatmiddelpunte, {0} mm uitmekaar.",
    "At each centre, draw the mounting hole AND a construction circle of radius equal to half the arm's width ({0} mm) — this guide circle is what the straight sides and end caps will be tangent to.": "Trek by elke middelpunt die monteergat EN 'n konstruksiesirkel met 'n radius gelyk aan die helfte van die arm se breedte ({0} mm) — die reguit kante en endkappe sal aan hierdie hulpsirkel raak.",
    "Because both guide circles share the same radius, the tangent sides are simply straight lines parallel to the centre line, offset by exactly that radius — draw both.": "Omdat albei hulpsirkels dieselfde radius het, is die raakkante eenvoudig reguit lyne ewewydig aan die middellyn, presies daardie radius daarvandaan — trek albei.",
    "Complete the outline with the two end arcs — the OUTER half of each guide circle, facing away from the body. The straight sides now blend smoothly into the arcs with no visible kink: a true tangent join.": "Voltooi die buitelyn met die twee endboë — die BUITESTE helfte van elke hulpsirkel, weg van die liggaam. Die reguit kante gaan nou glad oor in die boë sonder 'n sigbare knik: 'n ware raakaansluiting.",
    "Parallel Line Through a Point": "Ewewydige lyn deur 'n punt",
    "Draw a line through a given point, parallel to a given line, with compass and straightedge only: the four equal sides of a rhombus keep the opposite sides parallel.": "Trek 'n lyn deur 'n gegewe punt, ewewydig aan 'n gegewe lyn, met net 'n passer en reguitrand: die vier gelyke sye van 'n rombus hou die oorstaande sye ewewydig.",
    "Given line XY and point P, {0} mm above it. Construct a line through P parallel to XY. Show all construction.": "Gegee lyn XY en punt P, {0} mm daarbo. Konstrueer 'n lyn deur P ewewydig aan XY. Toon alle konstruksie.",
    "Draw the given line XY and mark point P, {0} mm above it.": "Trek die gegewe lyn XY en merk punt P, {0} mm daarbo.",
    "With P as centre and a radius of {0} mm, draw an arc that cuts XY at A.": "Trek met P as middelpunt en 'n radius van {0} mm 'n boog wat XY by A sny.",
    "With A as centre and the same radius, draw an arc through P that cuts XY again at B.": "Trek met A as middelpunt en dieselfde radius 'n boog deur P wat XY weer by B sny.",
    "With the same radius, draw arcs from P and from B. They cross at Q. (PABQ is a rhombus: all four sides are {0} mm.)": "Trek met dieselfde radius boë vanaf P en vanaf B. Hulle kruis by Q. (PABQ is 'n rombus: al vier sye is {0} mm.)",
    "Draw a line through P and Q, extended both ways: it is parallel to XY.": "Trek 'n lyn deur P en Q, in albei rigtings verleng: dit is ewewydig aan XY.",
    "Perpendicular From a Point to a Line": "Loodlyn vanaf 'n punt na 'n lyn",
    "Drop a perpendicular from a point to a line: the point and the meeting point of two equal arcs both lie on the perpendicular bisector of AB.": "Laat 'n loodlyn vanaf 'n punt na 'n lyn sak: die punt en die ontmoetingspunt van twee gelyke boë lê albei op die middelloodlyn van AB.",
    "Given line XY and point P, {0} mm above it. Construct the perpendicular from P to XY and label its foot N. Show all construction.": "Gegee lyn XY en punt P, {0} mm daarbo. Konstrueer die loodlyn vanaf P na XY en benoem sy voetpunt N. Toon alle konstruksie.",
    "Draw line XY and mark point P, {0} mm above it.": "Trek lyn XY en merk punt P, {0} mm daarbo.",
    "With P as centre, draw an arc that cuts XY at A and B.": "Trek met P as middelpunt 'n boog wat XY by A en B sny.",
    "With A and B as centres and the same radius (more than half of AB), draw two arcs below XY that cross at Q.": "Trek met A en B as middelpunte en dieselfde radius (meer as die helfte van AB) twee boë onder XY wat by Q kruis.",
    "Join P to Q. Where it crosses XY is N, the foot of the perpendicular. Mark the right angle.": "Verbind P met Q. Waar dit XY kruis, is N, die voetpunt van die loodlyn. Merk die regte hoek.",
    "Inscribed Circle of a Triangle": "Ingeskrewe sirkel van 'n driehoek",
    "The centre of the inscribed circle is where the angle bisectors meet: it is the same distance from all three sides.": "Die middelpunt van die ingeskrewe sirkel is waar die hoekhalveerlyne ontmoet: dit is ewe ver van al drie sye.",
    "Draw triangle ABC (AB = {0} mm, the other corners as shown) and construct its inscribed circle. Show all construction.": "Teken driehoek ABC (AB = {0} mm, die ander hoeke soos gewys) en konstrueer sy ingeskrewe sirkel. Toon alle konstruksie.",
    "Draw triangle ABC.": "Teken driehoek ABC.",
    "Bisect angle A: an arc from A cutting both sides, then two equal arcs from those points that cross inside the angle.": "Halveer hoek A: 'n boog vanaf A wat albei sye sny, dan twee gelyke boë vanaf daardie punte wat binne die hoek kruis.",
    "Draw the bisector of angle A from A through the crossing.": "Trek die halveerlyn van hoek A vanaf A deur die kruispunt.",
    "Bisect angle B the same way.": "Halveer hoek B op dieselfde manier.",
    "The bisectors cross at I, the centre of the inscribed circle. From I, construct a perpendicular to AB (or measure square to it) to find the radius IF.": "Die halveerlyne kruis by I, die middelpunt van die ingeskrewe sirkel. Konstrueer vanaf I 'n loodlyn op AB (of meet haaks daarop) om die radius IF te vind.",
    "With centre I and radius IF, draw the circle. It touches all three sides.": "Trek die sirkel met middelpunt I en radius IF. Dit raak al drie sye.",
    "Circumscribed Circle of a Triangle": "Omgeskrewe sirkel van 'n driehoek",
    "The centre of the circle through all three corners is where the perpendicular bisectors of the sides meet.": "Die middelpunt van die sirkel deur al drie hoeke is waar die middelloodlyne van die sye ontmoet.",
    "Draw triangle ABC as shown and construct the circle that passes through all three corners. Show all construction.": "Teken driehoek ABC soos gewys en konstrueer die sirkel wat deur al drie hoeke gaan. Toon alle konstruksie.",
    "Bisect side AB: equal arcs from A and B, more than half of AB, crossing above and below it.": "Halveer sy AB: gelyke boë vanaf A en B, meer as die helfte van AB, wat bo en onder dit kruis.",
    "Draw the perpendicular bisector of AB through the two crossings.": "Trek die middelloodlyn van AB deur die twee kruispunte.",
    "Bisect side BC the same way.": "Halveer sy BC op dieselfde manier.",
    "The bisectors cross at O. With centre O and radius OA, draw the circle: it passes through A, B and C.": "Die middelloodlyne kruis by O. Trek die sirkel met middelpunt O en radius OA: dit gaan deur A, B en C.",
    "Regular Heptagon on a Given Side (General Method)": "Reëlmatige sewehoek op 'n gegewe sy (algemene metode)",
    "The general method for any regular polygon on a given side: divide a semicircle into as many parts as the polygon has sides, and the lines from A through the divisions carry the corners.": "Die algemene metode vir enige reëlmatige veelhoek op 'n gegewe sy: verdeel 'n halfsirkel in soveel dele as wat die veelhoek sye het, en die lyne vanaf A deur die verdelings dra die hoeke.",
    "Construct a regular heptagon ({0} sides) on side AB = {1} mm using the general (semicircle) method. Show all construction.": "Konstrueer 'n reëlmatige sewehoek ({0} sye) op sy AB = {1} mm met die algemene (halfsirkel-) metode. Toon alle konstruksie.",
    "Draw side AB, {0} mm, and extend it to the left of A.": "Trek sy AB, {0} mm, en verleng dit links van A.",
    "With centre A and radius AB, draw a semicircle from the extension (B') over to B.": "Trek met middelpunt A en radius AB 'n halfsirkel vanaf die verlenging (B') oor na B.",
    "Divide the semicircle into {0} equal parts (each {1}°, by trial with dividers or with a protractor). Number them {2} to {3} from B'.": "Verdeel die halfsirkel in {0} gelyke dele (elk {1}°, deur probeer met 'n verdeelpasser of met 'n gradeboog). Nommer hulle {2} tot {3} vanaf B'.",
    "Join A to point {0}: this is the second side of the heptagon (the exterior angle is {1} × {2}°).": "Verbind A met punt {0}: dit is die tweede sy van die sewehoek (die buitehoek is {1} × {2}°).",
    "Draw thin lines from A through points {0}, {1}, {2} and {3}, and extend them well beyond the semicircle.": "Trek dun lyne vanaf A deur punte {0}, {1}, {2} en {3}, en verleng hulle ver verby die halfsirkel.",
    "With centre B and radius AB, cut the line through {0}. With the new point as centre, cut the line through {1}, and so on round the polygon.": "Sny met middelpunt B en radius AB die lyn deur {0}. Sny met die nuwe punt as middelpunt die lyn deur {1}, ensovoorts om die veelhoek.",
    "Join the corners to complete the heptagon.": "Verbind die hoeke om die sewehoek te voltooi.",
    "Tangent Arc Through a Point to a Circle": "Raakboog deur 'n punt aan 'n sirkel",
    "An arc of given radius through a point, touching a circle: its centre is R from the point and R + r from the circle's centre.": "'n Boog met 'n gegewe radius deur 'n punt, wat 'n sirkel raak: sy middelpunt is R van die punt en R + r van die sirkel se middelpunt.",
    "Given a circle (radius {0} mm) and point P. Construct an arc of radius {1} mm that passes through P and touches the circle on the outside. Show all construction.": "Gegee 'n sirkel (radius {0} mm) en punt P. Konstrueer 'n boog met radius {1} mm wat deur P gaan en die sirkel aan die buitekant raak. Toon alle konstruksie.",
    "Draw the given circle (radius {0}) with its centre lines, and mark point P.": "Trek die gegewe sirkel (radius {0}) met sy middellyne, en merk punt P.",
    "The centre of the arc is {0} mm from P: with centre P, draw an arc of radius {1}.": "Die middelpunt van die boog is {0} mm van P: trek met middelpunt P 'n boog met radius {1}.",
    "It is also {0} mm ({1} + {2}) from the circle's centre: draw an arc of that radius. The arcs cross at O.": "Dit is ook {0} mm ({1} + {2}) van die sirkel se middelpunt: trek 'n boog met daardie radius. Die boë kruis by O.",
    "Join O to the circle's centre. Where the line crosses the circle is the tangent point T.": "Verbind O met die sirkel se middelpunt. Waar die lyn die sirkel kruis, is die raakpunt T.",
    "With centre O and radius {0}, draw the arc from P to T.": "Trek met middelpunt O en radius {0} die boog vanaf P na T.",
    "Tangent Arc Outside Two Circles": "Raakboog buite twee sirkels",
    "An arc that touches two circles on the outside: its centre is R + r from each circle's centre, and the tangent points lie on the lines joining the centres.": "'n Boog wat twee sirkels aan die buitekant raak: sy middelpunt is R + r van elke sirkel se middelpunt, en die raakpunte lê op die lyne wat die middelpunte verbind.",
    "Given two circles, radius {0} and {1} mm, {2} mm apart. Construct an arc of radius {3} mm that touches both circles on the outside. Show all construction.": "Gegee twee sirkels, radius {0} en {1} mm, {2} mm uitmekaar. Konstrueer 'n boog met radius {3} mm wat albei sirkels aan die buitekant raak. Toon alle konstruksie.",
    "Draw the two circles with their centre lines.": "Trek die twee sirkels met hulle middellyne.",
    "From the left centre, draw an arc of radius {0} mm (R + r = {1} + {2}).": "Trek vanaf die linkermiddelpunt 'n boog met radius {0} mm (R + r = {1} + {2}).",
    "From the right centre, draw an arc of radius {0} mm ({1} + {2}). The arcs cross at O, the centre of the tangent arc.": "Trek vanaf die regtermiddelpunt 'n boog met radius {0} mm ({1} + {2}). Die boë kruis by O, die middelpunt van die raakboog.",
    "Join O to each circle centre. The lines cut the circles at T{0} and T{1}: the tangent points.": "Verbind O met elke sirkel se middelpunt. Die lyne sny die sirkels by T{0} en T{1}: die raakpunte.",
    "With centre O and radius {0}, draw the arc from T{1} to T{2}.": "Trek met middelpunt O en radius {0} die boog vanaf T{1} na T{2}.",
    "Tangent Arc Enclosing Two Circles": "Raakboog wat twee sirkels omsluit",
    "An arc that encloses both circles: its centre is R − r from each circle's centre, and the tangent points lie on the lines from the arc centre through the circle centres, extended.": "'n Boog wat albei sirkels omsluit: sy middelpunt is R − r van elke sirkel se middelpunt, en die raakpunte lê op die lyne vanaf die boog se middelpunt deur die sirkels se middelpunte, verleng.",
    "Given two circles, radius {0} and {1} mm, {2} mm apart. Construct an arc of radius {3} mm that touches both circles and encloses them. Show all construction.": "Gegee twee sirkels, radius {0} en {1} mm, {2} mm uitmekaar. Konstrueer 'n boog met radius {3} mm wat albei sirkels raak en hulle omsluit. Toon alle konstruksie.",
    "From the left centre, draw an arc of radius {0} mm (R − r = {1} − {2}).": "Trek vanaf die linkermiddelpunt 'n boog met radius {0} mm (R − r = {1} − {2}).",
    "From the right centre, draw an arc of radius {0} mm ({1} − {2}). The arcs cross at O, the centre of the tangent arc.": "Trek vanaf die regtermiddelpunt 'n boog met radius {0} mm ({1} − {2}). Die boë kruis by O, die middelpunt van die raakboog.",
    "Draw lines from O through each circle centre and extend them to cut the circles at T{0} and T{1}: the tangent points.": "Trek lyne vanaf O deur elke sirkel se middelpunt en verleng hulle om die sirkels by T{0} en T{1} te sny: die raakpunte.",
    "Tangent Arc Between Two Lines": "Raakboog tussen twee lyne",
    "Round off the corner between two lines with an arc of given radius: the centre is R from both lines, so it lies where two parallels, each R away, cross.": "Rond die hoek tussen twee lyne af met 'n boog met 'n gegewe radius: die middelpunt is R van albei lyne, dus lê dit waar twee ewewydige lyne, elk R weg, kruis.",
    "Two lines meet at {0}°. Join them with an arc of radius {1} mm. Show all construction and the tangent points.": "Twee lyne ontmoet teen {0}°. Verbind hulle met 'n boog met radius {1} mm. Toon alle konstruksie en die raakpunte.",
    "Draw the two lines meeting at {0}°.": "Trek die twee lyne wat teen {0}° ontmoet.",
    "Draw a thin line parallel to the bottom line, {0} mm inside the angle.": "Trek 'n dun lyn ewewydig aan die onderste lyn, {0} mm binne die hoek.",
    "Draw a thin line parallel to the sloping line, {0} mm inside the angle. The two parallels cross at O.": "Trek 'n dun lyn ewewydig aan die skuins lyn, {0} mm binne die hoek. Die twee ewewydige lyne kruis by O.",
    "From O, drop perpendiculars to both lines: the feet T{0} and T{1} are the tangent points.": "Laat vanaf O loodlyne na albei lyne sak: die voetpunte T{0} en T{1} is die raakpunte.",
    "With centre O and radius {0}, draw the arc from T{1} to T{2}, then line in the two straight parts up to the tangent points.": "Trek met middelpunt O en radius {0} die boog vanaf T{1} na T{2}, en trek dan die twee reguit dele tot by die raakpunte uit.",
    "Tangent Arc to a Line and a Circle": "Raakboog aan 'n lyn en 'n sirkel",
    "An arc touching a straight line and a circle: its centre is on a parallel R from the line and on an arc R + r from the circle's centre.": "'n Boog wat 'n reguit lyn en 'n sirkel raak: sy middelpunt lê op 'n ewewydige lyn R van die lyn en op 'n boog R + r van die sirkel se middelpunt.",
    "Given line XY and a circle of radius {0} mm. Construct an arc of radius {1} mm that touches both, on the left of the circle. Show all construction.": "Gegee lyn XY en 'n sirkel met radius {0} mm. Konstrueer 'n boog met radius {1} mm wat albei raak, links van die sirkel. Toon alle konstruksie.",
    "Draw line XY and the circle with its centre lines.": "Trek lyn XY en die sirkel met sy middellyne.",
    "Draw a thin line parallel to XY, {0} mm above it.": "Trek 'n dun lyn ewewydig aan XY, {0} mm daarbo.",
    "With the circle's centre, draw an arc of radius {0} mm ({1} + {2}) to cut the parallel at O.": "Trek vanaf die sirkel se middelpunt 'n boog met radius {0} mm ({1} + {2}) om die ewewydige lyn by O te sny.",
    "Drop a perpendicular from O to XY for T{0}, and join O to the circle's centre for T{1}.": "Laat 'n loodlyn vanaf O na XY sak vir T{0}, en verbind O met die sirkel se middelpunt vir T{1}.",
    "Copy a Figure: Lever with Tangents": "Kopieer 'n figuur: hefboom met raaklyne",
    "An original lever outline that combines two constructions: an external tangent line between two bosses, and a concave tangent arc underneath them.": "'n Oorspronklike hefboombuitelyn wat twee konstruksies kombineer: 'n buitenste raaklyn tussen twee nawe, en 'n hol raakboog daaronder.",
    "Copy the lever to scale {0}:{1}: bosses R{2} and R{3} at {4} mm centres, holes Ø{5} and Ø{6}, a straight tangent along the top and an R{7} tangent arc underneath. Show all construction.": "Kopieer die hefboom op skaal {0}:{1}: nawe R{2} en R{3} {4} mm van middelpunt tot middelpunt, gate Ø{5} en Ø{6}, 'n reguit raaklyn langs die bokant en 'n R{7}-raakboog daaronder. Toon alle konstruksie.",
    "Draw the centre lines and the two boss circles, R{0} and R{1}, {2} mm apart.": "Trek die middellyne en die twee naafsirkels, R{0} en R{1}, {2} mm uitmekaar.",
    "TOP TANGENT: with centre A, draw a thin circle of radius {0} mm (the difference of the radii).": "BOONSTE RAAKLYN: trek met middelpunt A 'n dun sirkel met radius {0} mm (die verskil van die radiusse).",
    "Bisect AB and draw a semicircle on it from the midpoint. It cuts the small circle at K (AK is square to BK).": "Halveer AB en trek vanaf die middelpunt 'n halfsirkel daarop. Dit sny die klein sirkel by K (AK is haaks op BK).",
    "Draw a line from A through K to the large circle: TA. Draw a parallel line from B to the small circle: TB. Join TA to TB.": "Trek 'n lyn vanaf A deur K na die groot sirkel: TA. Trek 'n ewewydige lyn vanaf B na die klein sirkel: TB. Verbind TA met TB.",
    "BOTTOM ARC (R{0}): from A draw an arc of radius {1} ({2} + {3}), and from B one of radius {4}. They cross at O, below the lever.": "ONDERSTE BOOG (R{0}): trek vanaf A 'n boog met radius {1} ({2} + {3}), en vanaf B een met radius {4}. Hulle kruis by O, onder die hefboom.",
    "Join O to A and to B to find the tangent points SA and SB, then draw the R{0} arc between them.": "Verbind O met A en met B om die raakpunte SA en SB te vind, en trek dan die R{0}-boog tussen hulle.",
    "Line in the outside of each boss between its tangent points, and draw the holes Ø{0} and Ø{1}.": "Trek die buitekant van elke naaf tussen sy raakpunte uit, en teken die gate Ø{0} en Ø{1}.",
    "Perpendicular at a Point on a Line": "Loodlyn by 'n punt op 'n lyn",
    "Erect a line at {0}° to a given line through a point on it: equal arcs from P mark two points, and arcs from those meet on the perpendicular.": "Rig 'n lyn teen {0}° op 'n gegewe lyn op deur 'n punt daarop: gelyke boë vanaf P merk twee punte, en boë vanaf daardie punte ontmoet op die loodlyn.",
    "Given line XY and point P on it. Construct a line through P perpendicular to XY. Show all construction.": "Gegee lyn XY en punt P daarop. Konstrueer 'n lyn deur P loodreg op XY. Toon alle konstruksie.",
    "Draw line XY and mark P on it.": "Trek lyn XY en merk P daarop.",
    "With centre P and radius {0}, cut XY on both sides of P at A and B.": "Sny met middelpunt P en radius {0} XY aan albei kante van P by A en B.",
    "With centres A and B and a larger radius ({0}), draw arcs that cross above the line at Q.": "Trek met middelpunte A en B en 'n groter radius ({0}) boë wat bo die lyn by Q kruis.",
    "Join P to Q and extend it: PQ is perpendicular to XY.": "Verbind P met Q en verleng dit: PQ is loodreg op XY.",
    "Perpendicular at the End of a Line": "Loodlyn by die ent van 'n lyn",
    "Erect a perpendicular at the end of a line without extending it: a circle through B, and a diameter of that circle, give a right angle at B (the angle in a semicircle).": "Rig 'n loodlyn by die ent van 'n lyn op sonder om dit te verleng: 'n sirkel deur B, en 'n middellyn van daardie sirkel, gee 'n regte hoek by B (die hoek in 'n halfsirkel).",
    "Given line AB. Construct a perpendicular to AB at B without extending the line. Show all construction.": "Gegee lyn AB. Konstrueer 'n loodlyn op AB by B sonder om die lyn te verleng. Toon alle konstruksie.",
    "Draw line AB.": "Trek lyn AB.",
    "Choose a point O above the line, near B. With centre O and radius OB, draw a circle that cuts AB again at C.": "Kies 'n punt O bo die lyn, naby B. Trek met middelpunt O en radius OB 'n sirkel wat AB weer by C sny.",
    "Draw a line from C through O to cut the circle at D. CD is a diameter.": "Trek 'n lyn vanaf C deur O om die sirkel by D te sny. CD is 'n middellyn.",
    "Join B to D: BD is perpendicular to AB (the angle in a semicircle is {0}°).": "Verbind B met D: BD is loodreg op AB (die hoek in 'n halfsirkel is {0}°).",
    "Parallel Line at a Given Distance": "Ewewydige lyn op 'n gegewe afstand",
    "Draw a line parallel to a given line, a fixed distance away: two arcs of that radius, and the common tangent to them.": "Trek 'n lyn ewewydig aan 'n gegewe lyn, 'n vaste afstand weg: twee boë met daardie radius, en die gemeenskaplike raaklyn daaraan.",
    "Given line XY. Construct a line parallel to XY and {0} mm from it. Show all construction.": "Gegee lyn XY. Konstrueer 'n lyn ewewydig aan XY en {0} mm daarvandaan. Toon alle konstruksie.",
    "Draw line XY.": "Trek lyn XY.",
    "Mark two points well apart on XY. With each as centre and radius {0}, draw an arc above the line.": "Merk twee punte ver uitmekaar op XY. Trek met elkeen as middelpunt en radius {0} 'n boog bo die lyn.",
    "Draw a line just touching the tops of both arcs (the common tangent). It is parallel to XY and {0} from it.": "Trek 'n lyn wat net-net die bokante van albei boë raak (die gemeenskaplike raaklyn). Dit is ewewydig aan XY en {0} daarvandaan.",
    "Equilateral Triangle on a Given Side": "Gelyksydige driehoek op 'n gegewe sy",
    "All three sides equal: arcs of radius AB from both ends of the side meet at the third corner.": "Al drie sye gelyk: boë met radius AB vanaf albei ente van die sy ontmoet by die derde hoek.",
    "Construct an equilateral triangle on a side AB of {0} mm. Show all construction.": "Konstrueer 'n gelyksydige driehoek op 'n sy AB van {0} mm. Toon alle konstruksie.",
    "Draw the side AB, {0} mm long.": "Trek die sy AB, {0} mm lank.",
    "With centre A and radius AB, draw an arc above the line.": "Trek met middelpunt A en radius AB 'n boog bo die lyn.",
    "With centre B and the same radius, draw an arc to cross the first one at C.": "Trek met middelpunt B en dieselfde radius 'n boog wat die eerste een by C kruis.",
    "Join A and B to C.": "Verbind A en B met C.",
    "Square on a Given Side": "Vierkant op 'n gegewe sy",
    "Erect a perpendicular at one end of the side, step the side length up it, and close the square with arcs.": "Rig 'n loodlyn by een ent van die sy op, stap die sylengte daarteen op, en maak die vierkant met boë toe.",
    "Construct a square on a side AB of {0} mm. Show all construction.": "Konstrueer 'n vierkant op 'n sy AB van {0} mm. Toon alle konstruksie.",
    "Draw the side AB, {0} mm long, extended a little to the left of A.": "Trek die sy AB, {0} mm lank, 'n bietjie links van A verleng.",
    "Erect a perpendicular at A: arcs of {0} from A mark the line on both sides; arcs of {1} from those points cross above A.": "Rig 'n loodlyn by A op: boë van {0} vanaf A merk die lyn aan albei kante; boë van {1} vanaf daardie punte kruis bo A.",
    "With centre A and radius {0}, cut the perpendicular at D.": "Sny met middelpunt A en radius {0} die loodlyn by D.",
    "With radius {0}, draw arcs from B and from D. They cross at C.": "Trek met radius {0} boë vanaf B en vanaf D. Hulle kruis by C.",
    "Line in the square ABCD.": "Trek die vierkant ABCD uit.",
    "Regular Hexagon on a Given Side": "Reëlmatige seshoek op 'n gegewe sy",
    "A hexagon is six equilateral triangles: the centre is found from the side, and the side length steps round the circle exactly six times.": "'n Seshoek is ses gelyksydige driehoeke: die middelpunt word vanaf die sy gevind, en die sylengte stap presies ses keer om die sirkel.",
    "Construct a regular hexagon on a side AB of {0} mm. Show all construction.": "Konstrueer 'n reëlmatige seshoek op 'n sy AB van {0} mm. Toon alle konstruksie.",
    "With radius {0}, draw arcs from A and B to cross at O: the centre of the hexagon.": "Trek met radius {0} boë vanaf A en B wat by O kruis: die middelpunt van die seshoek.",
    "With centre O and radius {0}, draw the circle through A and B.": "Trek met middelpunt O en radius {0} die sirkel deur A en B.",
    "Step the radius {0} round the circle from B: the other four corners.": "Stap die radius {0} vanaf B om die sirkel: die ander vier hoeke.",
    "Join the corners to complete the hexagon.": "Verbind die hoeke om die seshoek te voltooi.",
    "Regular Octagon on a Given Side": "Reëlmatige agthoek op 'n gegewe sy",
    "Each outside angle of an octagon is {0}°: build it round from the given side with the {1}° set square, stepping the side length each time.": "Elke buitehoek van 'n agthoek is {0}°: bou dit vanaf die gegewe sy om met die {1}°-tekendriehoek, en stap elke keer die sylengte af.",
    "Construct a regular octagon on a side AB of {0} mm, using the {1}° set square. Show all construction.": "Konstrueer 'n reëlmatige agthoek op 'n sy AB van {0} mm, met die {1}°-tekendriehoek. Toon alle konstruksie.",
    "With the {0}° set square, draw lines at {1}° up and out from A and from B. Mark {2} along each.": "Trek met die {0}°-tekendriehoek lyne teen {1}° op en uit vanaf A en vanaf B. Merk {2} langs elkeen af.",
    "From those corners draw vertical sides {0} long.": "Trek vanaf daardie hoeke vertikale sye van {0} lank.",
    "From their tops draw lines at {0}° inwards, {1} long, and join the last two corners: the top side is parallel to AB.": "Trek vanaf hulle bokante lyne teen {0}° na binne, {1} lank, en verbind die laaste twee hoeke: die boonste sy is ewewydig aan AB.",
    "Line in the octagon.": "Trek die agthoek uit.",
    "Regular Octagon in a Square": "Reëlmatige agthoek in 'n vierkant",
    "An octagon cut from a square: arcs from each corner with radius half the diagonal mark the eight corners on the sides.": "'n Agthoek uit 'n vierkant gesny: boë vanaf elke hoek met 'n radius van die halwe hoeklyn merk die agt hoeke op die sye.",
    "Construct a regular octagon inside a {0} mm square. Show all construction.": "Konstrueer 'n reëlmatige agthoek binne 'n vierkant van {0} mm. Toon alle konstruksie.",
    "Draw the {0} mm square and its two diagonals. They cross at the centre O.": "Teken die vierkant van {0} mm en sy twee hoeklyne. Hulle kruis by die middelpunt O.",
    "With each corner as centre and radius from the corner to O (half the diagonal), draw arcs to cut the two sides next to it.": "Trek met elke hoek as middelpunt en die radius van die hoek tot O (die halwe hoeklyn) boë om die twee sye langsaan te sny.",
    "The eight cuts are the corners of the octagon. Join them.": "Die agt snypunte is die hoeke van die agthoek. Verbind hulle.",
    "Find the Centre of a Circle": "Vind die middelpunt van 'n sirkel",
    "The perpendicular bisector of any chord passes through the centre: bisect two chords and the bisectors cross at it.": "Die middelloodlyn van enige koord gaan deur die middelpunt: halveer twee koorde en die middelloodlyne kruis daar.",
    "A circle is given without its centre. Find the centre by construction. Show all construction.": "'n Sirkel word sonder sy middelpunt gegee. Vind die middelpunt deur konstruksie. Toon alle konstruksie.",
    "Draw the given circle (its centre is not known).": "Trek die gegewe sirkel (sy middelpunt is nie bekend nie).",
    "Draw two chords AB and CD that are not parallel.": "Trek twee koorde AB en CD wat nie ewewydig is nie.",
    "Bisect chord AB (equal arcs from A and B; join the crossings).": "Halveer koord AB (gelyke boë vanaf A en B; verbind die kruispunte).",
    "Bisect chord CD the same way. The bisectors cross at O, the centre.": "Halveer koord CD op dieselfde manier. Die middelloodlyne kruis by O, die middelpunt.",
    "Tangent Arc in a Right Angle": "Raakboog in 'n regte hoek",
    "Round the corner between two lines with an arc of radius {0}: its centre is {1} from both lines, where two parallels meet.": "Rond die hoek tussen twee lyne af met 'n boog met radius {0}: sy middelpunt is {1} van albei lyne, waar twee ewewydige lyne ontmoet.",
    "Draw a parallel to each line, {0} mm inside the angle (arcs of {1} and a tangent, or the set square). They cross at O.": "Trek 'n ewewydige lyn aan elke lyn, {0} mm binne die hoek (boë van {1} en 'n raaklyn, of die tekendriehoek). Hulle kruis by O.",
    "Drop perpendiculars from O to both lines: the tangent points T{0} and T{1}.": "Laat loodlyne vanaf O na albei lyne sak: die raakpunte T{0} en T{1}.",
    "Draw the R{0} arc from T{1} to T{2} and line in the straight parts.": "Trek die R{0}-boog vanaf T{1} na T{2} en trek die reguit dele uit.",
    "Tangent Arc in an Obtuse Angle": "Raakboog in 'n stomp hoek",
    "Open Belt: External Tangents to Two Circles": "Oop band: buitenste raaklyne aan twee sirkels",
    "An open belt: the two external tangents. The construction circle has radius R − r, the difference of the radii.": "'n Oop band: die twee buitenste raaklyne. Die konstruksiesirkel het radius R − r, die verskil van die radiusse.",
    "Two pulleys, R{0} and R{1}, are {2} mm apart. Draw an open belt (external tangents) round them. Show all construction.": "Twee katrolle, R{0} en R{1}, is {2} mm uitmekaar. Teken 'n oop band (buitenste raaklyne) om hulle. Toon alle konstruksie.",
    "Draw the two pulleys with their centre lines.": "Teken die twee katrolle met hulle middellyne.",
    "From A draw a thin circle of radius {0} ({1} − {2}).": "Trek vanaf A 'n dun sirkel met radius {0} ({1} − {2}).",
    "Bisect AB and draw a circle on AB as diameter. It cuts the thin circle at K{0} and K{1}.": "Halveer AB en trek 'n sirkel met AB as middellyn. Dit sny die dun sirkel by K{0} en K{1}.",
    "Draw lines from A through K{0} and K{1} to the big pulley: two tangent points. From B draw lines parallel to them: the other two.": "Trek lyne vanaf A deur K{0} en K{1} na die groot katrol: twee raakpunte. Trek vanaf B lyne ewewydig daaraan: die ander twee.",
    "Join the tangent points in pairs: the belt.": "Verbind die raakpunte in pare: die band.",
    "Crossed Belt: Internal Tangents to Two Circles": "Gekruiste band: binneste raaklyne aan twee sirkels",
    "A crossed belt: the two internal tangents cross between the pulleys. The construction circle has radius R + r.": "'n Gekruiste band: die twee binneste raaklyne kruis tussen die katrolle. Die konstruksiesirkel het radius R + r.",
    "Two pulleys, R{0} and R{1}, are {2} mm apart. Draw a crossed belt (internal tangents) round them. Show all construction.": "Twee katrolle, R{0} en R{1}, is {2} mm uitmekaar. Teken 'n gekruiste band (binneste raaklyne) om hulle. Toon alle konstruksie.",
    "From A draw a thin circle of radius {0} ({1} + {2}).": "Trek vanaf A 'n dun sirkel met radius {0} ({1} + {2}).",
    "Draw lines from A through K{0} and K{1} to the big pulley: two tangent points. From B draw lines parallel to them, on the opposite side: the other two.": "Trek lyne vanaf A deur K{0} en K{1} na die groot katrol: twee raakpunte. Trek vanaf B lyne ewewydig daaraan, aan die teenoorgestelde kant: die ander twee.",
    "Ellipse: Rectangle Method": "Ellips: reghoekmetode",
    "Divide the half-side and half-length of the enclosing rectangle into the same number of parts; lines from the ends of the axes cross on the ellipse.": "Verdeel die halwe sy en halwe lengte van die omhullende reghoek in dieselfde aantal dele; lyne vanaf die ente van die asse kruis op die ellips.",
    "Construct an ellipse with a major axis of {0} mm and a minor axis of {1} mm by the rectangle method. Show the construction for one quarter, then complete the curve.": "Konstrueer 'n ellips met 'n hoofas van {0} mm en 'n neweas van {1} mm met die reghoekmetode. Toon die konstruksie vir een kwart, en voltooi dan die kromme.",
    "Draw the major axis ({0}) and minor axis ({1}) crossing at the centre, and the rectangle round them.": "Trek die hoofas ({0}) en neweas ({1}) wat by die middelpunt kruis, en die reghoek om hulle.",
    "Divide AD (half the short side, from A at the end of the major axis up to the corner D) and OA (half the major axis) into {0} equal parts each. Number both from A.": "Verdeel AD (die halwe kort sy, vanaf A aan die ent van die hoofas op tot by hoek D) en OA (die halwe hoofas) elk in {0} gelyke dele. Nommer albei vanaf A.",
    "Join the points on AD to C, the top end of the minor axis. From E, the bottom end, draw lines through the points on OA and extend them upwards.": "Verbind die punte op AD met C, die boonste ent van die neweas. Trek vanaf E, die onderste ent, lyne deur die punte op OA en verleng hulle opwaarts.",
    "Lines with the same number cross on the ellipse. Mark the points, then repeat for the other three quarters.": "Lyne met dieselfde nommer kruis op die ellips. Merk die punte, en herhaal dan vir die ander drie kwarte.",
    "Draw a smooth curve through all the points.": "Trek 'n gladde kromme deur al die punte.",
    "Angles of {0}°, {1}°, {2}° and {3}° by Compass": "Hoeke van {0}°, {1}°, {2}° en {3}° met die passer",
    "Every set-square angle can be made with a compass: {0}° from an equilateral triangle, {1}° by bisecting it, {2}° from two {3}° steps bisected, and {4}° by bisecting {5}°.": "Elke tekendriehoekhoek kan met 'n passer gemaak word: {0}° uit 'n gelyksydige driehoek, {1}° deur dit te halveer, {2}° uit twee stappe van {3}° gehalveer, en {4}° deur {5}° te halveer.",
    "From point V on line VX, construct angles of {0}°, {1}°, {2}° and {3}° with compass and ruler only. Show all construction.": "Konstrueer vanaf punt V op lyn VX hoeke van {0}°, {1}°, {2}° en {3}° met net 'n passer en liniaal. Toon alle konstruksie.",
    "Draw line VX. With centre V and radius {0}, draw a large arc cutting VX at A.": "Trek lyn VX. Trek met middelpunt V en radius {0} 'n groot boog wat VX by A sny.",
    "{0}°: with centre A and the same radius, cut the arc at B. VB is at {1}° to VX.": "{0}°: sny met middelpunt A en dieselfde radius die boog by B. VB is teen {1}° met VX.",
    "{0}°: bisect the angle AVB (equal arcs from A and B). The bisector is at {1}°.": "{0}°: halveer hoek AVB (gelyke boë vanaf A en B). Die halveerlyn is teen {1}°.",
    "{0}°: from B step the radius again to C ({1}°), then bisect angle BVC. The bisector is at {2}°.": "{0}°: stap vanaf B die radius weer af na C ({1}°), en halveer dan hoek BVC. Die halveerlyn is teen {2}°.",
    "{0}°: bisect the {1}° angle (between VX and the vertical).": "{0}°: halveer die hoek van {1}° (tussen VX en die vertikaal).",
    "Divide a Circle into Twelve Equal Parts": "Verdeel 'n sirkel in twaalf gelyke dele",
    "The radius steps round a circle six times; from the four ends of two diameters, each step lands on a {0}° division: twelve parts with the compass only (used for helices and cams).": "Die radius stap ses keer om 'n sirkel; vanaf die vier ente van twee middellyne land elke stap op 'n verdeling van {0}°: twaalf dele met net die passer (gebruik vir helikse en nokke).",
    "Divide a circle of radius {0} mm into twelve equal parts with the compass. Number the points {1} to {2}.": "Verdeel 'n sirkel met radius {0} mm met die passer in twaalf gelyke dele. Nommer die punte {1} tot {2}.",
    "Draw the circle and two diameters at right angles.": "Trek die sirkel en twee middellyne haaks op mekaar.",
    "With radius {0} and each of the four ends of the diameters as centre, cut the circle on both sides.": "Sny met radius {0} en elk van die vier ente van die middellyne as middelpunt die sirkel aan albei kante.",
    "The cuts and the four ends give twelve equal divisions of {0}°. Number them {1} to {2} and draw radial lines.": "Die snypunte en die vier ente gee twaalf gelyke verdelings van {0}°. Nommer hulle {1} tot {2} en trek radiale lyne.",
    "Copy a Figure: Rocker Arm": "Kopieer 'n figuur: wipperarm",
    "A three-boss rocker arm: a straight tangent, an enclosing arc over the right-hand end and a concave arc underneath.": "'n Wipperarm met drie nawe: 'n reguit raaklyn, 'n omsluitende boog oor die regterkantse ent en 'n hol boog daaronder.",
    "Copy the rocker arm to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}. A to B is {8} right and {9} up; A to C is {10} right and {11} up. A straight tangent joins A and B, an R{12} arc encloses B and C, and an R{13} concave arc joins C and A underneath. Show all constructions for the tangents and tangent arcs.": "Kopieer die wipperarm op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}. A na B is {8} regs en {9} op; A na C is {10} regs en {11} op. 'n Reguit raaklyn verbind A en B, 'n R{12}-boog omsluit B en C, en 'n hol R{13}-boog verbind C en A onder." + SHOW,
    "Copy a Figure: Link with Concave Sides": "Kopieer 'n figuur: skakel met hol kante",
    "A two-boss link waisted on both sides by R{0} concave arcs: the same construction twice, above and below.": "'n Skakel met twee nawe wat aan albei kante deur hol R{0}-boë ingesnoer is: dieselfde konstruksie twee keer, bo en onder.",
    "Copy the concave link to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}. The bosses are {6} apart on one horizontal centre line. R{7} concave arcs join them above and below. Show all constructions for the tangents and tangent arcs.": "Kopieer die hol skakel op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}. Die nawe is {6} uitmekaar op een horisontale middellyn. Hol R{7}-boë verbind hulle bo en onder." + SHOW,
    "Draw each boss as a thin circle: A R{0}, B R{1}.": "Trek elke naaf as 'n dun sirkel: A R{0}, B R{1}.",
    "Draw the holes: Ø{0}, Ø{1}.": "Teken die gate: Ø{0}, Ø{1}.",
    "Copy a Figure: Four-Hole Mounting Plate": "Kopieer 'n figuur: monteerplaat met vier gate",
    "A mounting plate with four equal corner bosses: straight sides, R{0} concave arcs top and bottom, and a central hole.": "'n Monteerplaat met vier gelyke hoeknawe: reguit kante, hol R{0}-boë bo en onder, en 'n gat in die middel.",
    "Copy the mounting plate to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}; D: R{8}, hole Ø{9}. The hole centres form a rectangle {10} × {11}. The ends are straight tangents; the top and bottom are R{12} concave arcs. A Ø{13} hole is in the middle. Show all constructions for the tangents and tangent arcs.": "Kopieer die monteerplaat op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}; D: R{8}, gat Ø{9}. Die gatmiddelpunte vorm 'n reghoek van {10} × {11}. Die ente is reguit raaklyne; die bo- en onderkant is hol R{12}-boë. 'n Ø{13}-gat is in die middel." + SHOW,
    "Draw the holes: Ø{0}, Ø{1}, Ø{2}, Ø{3}. Add the Ø{4} central hole.": "Teken die gate: Ø{0}, Ø{1}, Ø{2}, Ø{3}. Voeg die Ø{4}-gat in die middel by.",
    "Copy a Figure: Cam Lever": "Kopieer 'n figuur: nokhefboom",
    "A lever with a straight top edge and a large R{0} arc enclosing both bosses underneath.": "'n Hefboom met 'n reguit boonste rand en 'n groot R{0}-boog wat albei nawe onder omsluit.",
    "Copy the cam lever to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}. B is {6} right and {7} up from A. A straight tangent joins the bosses along the top; an R{8} arc encloses both bosses underneath. Show all constructions for the tangents and tangent arcs.": "Kopieer die nokhefboom op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}. B is {6} regs en {7} op van A. 'n Reguit raaklyn verbind die nawe langs die bokant; 'n R{8}-boog omsluit albei nawe onder." + SHOW,
    "Copy a Figure: Triangular Link Plate": "Kopieer 'n figuur: driehoekige skakelplaat",
    "Three equal bosses: straight tangents on two sides and an R{0} concave arc along the base, with a lightening hole.": "Drie gelyke nawe: reguit raaklyne aan twee kante en 'n hol R{0}-boog langs die basis, met 'n verligtingsgat.",
    "Copy the triangular link plate to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}. A and C are {8} apart; B is {9} right of A and {10} up. Straight tangents join A-B and B-C; an R{11} concave arc joins C and A. A Ø{12} hole is at {13} right and {14} up from A. Show all constructions for the tangents and tangent arcs.": "Kopieer die driehoekige skakelplaat op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}. A en C is {8} uitmekaar; B is {9} regs van A en {10} op. Reguit raaklyne verbind A-B en B-C; 'n hol R{11}-boog verbind C en A. 'n Ø{12}-gat is {13} regs en {14} op van A." + SHOW,
    "Draw the holes: Ø{0}, Ø{1}, Ø{2}. Add the Ø{3} lightening hole.": "Teken die gate: Ø{0}, Ø{1}, Ø{2}. Voeg die Ø{3}-verligtingsgat by.",
    "Copy a Figure: Crank": "Kopieer 'n figuur: kruk",
    "A tapered crank: two external tangents, one above and one below, between unequal bosses.": "'n Tapse kruk: twee buitenste raaklyne, een bo en een onder, tussen ongelyke nawe.",
    "Copy the crank to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}. The bosses are {6} apart on one horizontal centre line. Straight tangents join them above and below. Show all constructions for the tangents and tangent arcs.": "Kopieer die kruk op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}. Die nawe is {6} uitmekaar op een horisontale middellyn. Reguit raaklyne verbind hulle bo en onder." + SHOW,
    "Draw the holes: Ø{0}, Ø{1}. Add the {2} mm key flat in the large hole (thin square marks the flat position).": "Teken die gate: Ø{0}, Ø{1}. Voeg die {2} mm-spieplat in die groot gat by ('n dun vierkantjie merk die plat se posisie).",
    "Copy a Figure: Bell Crank": "Kopieer 'n figuur: klokkruk",
    "An L-shaped bell crank: straight outside edges and an R{0} concave arc in the inside corner.": "'n L-vormige klokkruk: reguit buiterande en 'n hol R{0}-boog in die binnehoek.",
    "Copy the bell crank to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}. A is {8} above B; C is {9} to the right of B. Straight tangents join A-B and B-C on the outside; an R{10} concave arc joins C and A in the inside corner. Show all constructions for the tangents and tangent arcs.": "Kopieer die klokkruk op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}. A is {8} bo B; C is {9} regs van B. Reguit raaklyne verbind A-B en B-C aan die buitekant; 'n hol R{10}-boog verbind C en A in die binnehoek." + SHOW,
    "Copy a Figure: Pedal Arm": "Kopieer 'n figuur: pedaalarm",
    "A three-boss pedal arm: a concave arc underneath, a straight edge on the right and a big enclosing arc over the top.": "'n Pedaalarm met drie nawe: 'n hol boog onder, 'n reguit rand regs en 'n groot omsluitende boog oor die bokant.",
    "Copy the pedal arm to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}. B is {8} right and {9} down from A; C is {10} right and {11} up from A. An R{12} concave arc joins A and B, a straight tangent joins B and C, and an R{13} arc encloses C and A over the top. Show all constructions for the tangents and tangent arcs.": "Kopieer die pedaalarm op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}. B is {8} regs en {9} af van A; C is {10} regs en {11} op van A. 'n Hol R{12}-boog verbind A en B, 'n reguit raaklyn verbind B en C, en 'n R{13}-boog omsluit C en A oor die bokant." + SHOW,
    "Copy a Figure: Clamp Jaw": "Kopieer 'n figuur: klembek",
    "A four-boss clamp jaw mixing all three joints: straight tangents, an enclosing arc and a concave arc.": "'n Klembek met vier nawe wat al drie aansluitings meng: reguit raaklyne, 'n omsluitende boog en 'n hol boog.",
    "Copy the clamp jaw to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}; D: R{8}, hole Ø{9}. From A: B is {10} right and {11} up, C is {12} right and {13} down, D is {14} right and {15} down. Straight tangents join A-B and D-A, an R{16} arc encloses B and C, and an R{17} concave arc joins C and D. Show all constructions for the tangents and tangent arcs.": "Kopieer die klembek op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}; D: R{8}, gat Ø{9}. Vanaf A: B is {10} regs en {11} op, C is {12} regs en {13} af, D is {14} regs en {15} af. Reguit raaklyne verbind A-B en D-A, 'n R{16}-boog omsluit B en C, en 'n hol R{17}-boog verbind C en D." + SHOW,
    "Copy a Figure: Hanger Bracket": "Kopieer 'n figuur: hangerhakie",
    "A hanger: two fixing lugs with an R{0} concave top edge, and R{1} concave arcs sweeping down to the bearing boss.": "'n Hanger: twee bevestigingsore met 'n hol R{0}-boonste rand, en hol R{1}-boë wat afswaai na die laernaaf.",
    "Copy the hanger bracket to scale {0}:{1}. Bosses A: R{2}, hole Ø{3}; B: R{4}, hole Ø{5}; C: R{6}, hole Ø{7}. A and B are {8} apart on one horizontal line; C is midway, {9} below. An R{10} concave arc joins A and B; R{11} concave arcs join B-C and C-A. Show all constructions for the tangents and tangent arcs.": "Kopieer die hangerhakie op skaal {0}:{1}. Nawe A: R{2}, gat Ø{3}; B: R{4}, gat Ø{5}; C: R{6}, gat Ø{7}. A en B is {8} uitmekaar op een horisontale lyn; C is halfpad, {9} laer. 'n Hol R{10}-boog verbind A en B; hol R{11}-boë verbind B-C en C-A." + SHOW
  });
  window.DD_AF = T;
})();
